begin;select plan(7);select has_function('public','claim_expired_evidence',array['integer','uuid']);select has_function('public','finalize_evidence_deletion',array['uuid','uuid']);select ok(exists(select 1 from information_schema.columns where table_schema='private'and table_name='evidence_objects'and column_name='legal_hold_at'),'legal hold');select ok(exists(select 1 from information_schema.columns where table_schema='private'and table_name='evidence_objects'and column_name='appeal_at'),'appeal');select ok(exists(select 1 from pg_indexes where indexname='evidence_retention_due_idx'),'deadline index');select ok(not has_function_privilege('authenticated','public.claim_expired_evidence(integer,uuid)','EXECUTE'),'scheduler only');select ok(exists(select 1 from pg_proc where oid=to_regprocedure('public.claim_expired_evidence(integer,uuid)')and lower(prosrc)like'%skip locked%'),'concurrent claims');select*from finish();rollback;
